import pygame
from constants import *

class Block:
    def __init__(self, x, y, btype, content=None):
        self.x = x
        self.y = y
        self.w = TILE
        self.h = TILE
        self.type = btype  # 'ground', 'brick', 'question', 'pipe'
        self.content = content  # 'coin', 'mushroom', 'star', 'fire_flower', None
        self.hit = False       # 方块已撞击
        self.broken = False    # 砖块已破碎
        self.bump_y = 0        # 顶砖动画偏移
        self.frame = 0
        # pipe特有
        self.pipe_h = 0

    def update(self):
        self.frame += 1
        # 顶砖反弹动画
        if self.bump_y < 0:
            self.bump_y += 1.5
            if self.bump_y > 0:
                self.bump_y = 0

    def hit_block(self):
        """从下方撞击方块，返回 'coin', 'mushroom', 'star', 'fire_flower', 'break', None"""
        if self.type == 'question' and not self.hit:
            self.hit = True
            self.bump_y = -8
            return self.content
        elif self.type == 'brick' and not self.hit:
            self.hit = True
            self.broken = True
            self.bump_y = -8
            return 'break'
        elif self.type == 'brick':
            self.bump_y = -4
            return None
        elif self.type == 'question' and self.hit:
            self.bump_y = -4
            return None
        return None

    def is_solid(self):
        if self.broken:
            return False
        if self.type == 'ground':
            return True
        if self.type == 'pipe':
            return True
        if self.type in ('brick', 'question'):
            return True
        return False

    def draw(self, surface, cam_x):
        if self.broken:
            return
        sx = self.x - int(cam_x)
        sy = self.y + self.bump_y

        if sx < -TILE or sx > SCREEN_W + TILE:
            return

        if self.type == 'ground':
            pygame.draw.rect(surface, BROWN, (sx, sy, self.w, self.h))
            pygame.draw.rect(surface, DARK_BROWN, (sx, sy, self.w, self.h), 2)
            # 地面纹理线
            for i in range(0, self.w, 10):
                pygame.draw.line(surface, DARK_BROWN, (sx + i, sy), (sx + i, sy + self.h), 1)

        elif self.type == 'brick':
            if not self.hit:
                pygame.draw.rect(surface, BRICK_COLOR, (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, DARK_BROWN, (sx, sy, self.w, self.h), 2)
                # 砖纹理
                pygame.draw.line(surface, DARK_BROWN, (sx, sy + self.h // 2), (sx + self.w, sy + self.h // 2), 2)
                pygame.draw.line(surface, DARK_BROWN, (sx + self.w // 2, sy), (sx + self.w // 2, sy + self.h // 2), 1)
            else:
                # 已顶过的砖变暗
                pygame.draw.rect(surface, (120, 70, 30), (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, DARK_BROWN, (sx, sy, self.w, self.h), 2)

        elif self.type == 'question':
            if not self.hit:
                pygame.draw.rect(surface, QUESTION_COLOR, (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, (180, 150, 30), (sx, sy, self.w, self.h), 2)
                # ? 标记
                font = pygame.font.SysFont("Arial", 22, bold=True)
                q = font.render("?", True, WHITE)
                surface.blit(q, (sx + 12, sy + 8))
            else:
                pygame.draw.rect(surface, (120, 100, 30), (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, (80, 60, 20), (sx, sy, self.w, self.h), 2)

        elif self.type == 'pipe':
            pipe_h = self.pipe_h if self.pipe_h > 0 else self.h
            pygame.draw.rect(surface, PIPE_COLOR, (sx, sy, self.w, pipe_h))
            pygame.draw.rect(surface, PIPE_DARK, (sx, sy, self.w, pipe_h), 2)
            # 管道口
            lip_h = 8
            pygame.draw.rect(surface, PIPE_DARK, (sx - 4, sy, self.w + 8, lip_h))
            pygame.draw.rect(surface, PIPE_COLOR, (sx - 4, sy, self.w + 8, lip_h), 2)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

    def get_top_rect(self):
        """用于玩家站在上面的碰撞"""
        return pygame.Rect(self.x, self.y, self.w, self.h)

    def get_bottom_rect(self):
        """用于玩家顶撞的碰撞"""
        return pygame.Rect(self.x, self.y, self.w, self.h)

import pygame
from constants import *

class Coin:
    def __init__(self, x, y):
        self.x = float(x)
        self.y = float(y)
        self.r = 10
        self.collected = False
        self.frame = 0
        self.bob_offset = 0

    def update(self):
        self.frame += 1
        self.bob_offset = (self.frame // 4) % 2  # 2像素上下浮动

    def collect(self):
        if not self.collected:
            self.collected = True
            return True
        return False

    def draw(self, surface, cam_x):
        if self.collected:
            return
        sx = self.x - int(cam_x)
        sy = self.y + self.bob_offset
        if sx < -20 or sx > SCREEN_W + 20:
            return
        # 金币旋转模拟
        squash = abs((self.frame % 30) - 15) / 15.0
        r = max(3, int(self.r * (0.5 + squash * 0.5)))
        pygame.draw.circle(surface, COIN_COLOR, (int(sx), int(sy + self.r)), r)
        pygame.draw.circle(surface, (200, 160, 10), (int(sx), int(sy + self.r)), r, 1)

    def get_rect(self):
        return pygame.Rect(self.x, self.y - self.r, self.r * 2, self.r * 2)


class Flag:
    def __init__(self, x, y, pole_height=240):
        self.x = float(x)
        self.y = float(y)
        self.pole_height = pole_height
        self.flag_y = float(y)
        self.collected = False
        self.frame = 0

    def update(self):
        self.frame += 1
        if self.collected:
            self.flag_y += 3

    def use(self):
        if not self.collected:
            self.collected = True
            return True
        return False

    def draw(self, surface, cam_x):
        sx = self.x - int(cam_x)
        if sx < -20 or sx > SCREEN_W + 20:
            return
        # 旗杆
        pygame.draw.line(surface, POLE_COLOR, (sx, self.y), (sx, self.y - self.pole_height), 4)
        # 顶部球
        pygame.draw.circle(surface, GREEN, (int(sx), int(self.y - self.pole_height)), 6)
        # 旗帜
        if not self.collected:
            flag_w = 24
            flag_h = 20
            flag_y = self.y - self.pole_height + 20
            pygame.draw.polygon(surface, GREEN, [
                (sx, flag_y),
                (sx - flag_w, flag_y + flag_h // 2),
                (sx, flag_y + flag_h)
            ])
        else:
            # 旗帜滑下
            flag_y = self.flag_y - self.pole_height + 20
            pygame.draw.polygon(surface, GREEN, [
                (sx, flag_y),
                (sx - 24, flag_y + 10),
                (sx, flag_y + 20)
            ])

    def get_rect(self):
        return pygame.Rect(self.x - 10, self.y - self.pole_height, 20, self.pole_height + 10)

import pygame
from constants import *

class PowerUp:
    def __init__(self, x, y, ptype):
        self.x = float(x)
        self.y = float(y)
        self.w = 24
        self.h = 24
        self.type = ptype  # 'mushroom', 'star', 'fire_flower'
        self.vx = 1.5
        self.vy = 0.0
        self.active = True
        self.emerging = True
        self.emerged_y = y - TILE  # 最终显示位置（方块上方）
        self.frame = 0

    def update(self, solids):
        self.frame += 1
        if not self.active:
            return

        # 升起动画
        if self.emerging:
            if self.y > self.emerged_y:
                self.y -= 2
                return
            else:
                self.emerging = False
            return  # 首次完全露出后下一帧再移动

        # 重力
        self.vy += GRAVITY
        if self.vy > MAX_FALL:
            self.vy = MAX_FALL

        # 水平移动
        self.x += self.vx
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vx > 0:
                    self.x = s.left - self.w
                else:
                    self.x = s.right
                self.vx = -self.vx
                break

        # 垂直
        self.y += self.vy
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vy > 0:
                    self.y = s.top - self.h
                    self.vy = 0
                break

        # 掉落死亡
        if self.y > 800:
            self.active = False

    def draw(self, surface, cam_x):
        if not self.active:
            return
        sx = self.x - int(cam_x)
        sy = self.y
        if sx < -30 or sx > SCREEN_W + 30:
            return

        if self.type == 'mushroom':
            # 红蘑菇
            pygame.draw.ellipse(surface, (200, 50, 50), (sx, sy, self.w, self.h))
            pygame.draw.ellipse(surface, (255, 255, 255), (sx + 8, sy + 4, 8, 8))
            # 斑点
            pygame.draw.circle(surface, WHITE, (int(sx + 6), int(sy + 10)), 3)
            pygame.draw.circle(surface, WHITE, (int(sx + 18), int(sy + 10)), 3)
            # 茎
            pygame.draw.rect(surface, (230, 210, 180), (sx + 4, sy + 14, 16, 10))
        elif self.type == 'star':
            # 星星
            pygame.draw.circle(surface, YELLOW, (int(sx + 12), int(sy + 12)), 12)
            pts = []
            for i in range(5):
                angle = self.frame * 0.1 + i * 3.14159 * 2 / 5 - 3.14159 / 2
                pts.append((sx + 12 + 12 * pygame.math.Vector2(1, 0).rotate(angle * 180 / 3.14159).x,
                            sy + 12 + 12 * pygame.math.Vector2(1, 0).rotate(angle * 180 / 3.14159).y))
            if len(pts) >= 5:
                pygame.draw.polygon(surface, (255, 255, 0), pts)
                pygame.draw.polygon(surface, (200, 200, 0), pts, 1)
        elif self.type == 'fire_flower':
            # 火焰花
            for i in range(6):
                angle = self.frame * 0.05 + i * 3.14159 / 3
                px = sx + 12 + 10 * pygame.math.Vector2(1, 0).rotate(angle * 180 / 3.14159).x
                py = sy + 12 + 10 * pygame.math.Vector2(1, 0).rotate(angle * 180 / 3.14159).y
                pygame.draw.circle(surface, (255, 100, 0), (int(px), int(py)), 4)
            pygame.draw.circle(surface, (255, 200, 0), (int(sx + 12), int(sy + 12)), 6)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

    def activate(self, player):
        """被玩家拾取时的效果"""
        if self.type == 'mushroom':
            player.grow()
        elif self.type == 'star':
            player.star_power()
        elif self.type == 'fire_flower':
            player.fire_power()
        self.active = False
